Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis container

Container_Boundary(redis, "Redis") {
    Component(RedisClusterCoordinatorProxy, "Redis Cluster Coordinator / Proxy", "Redis Cluster Coordinator", "Manages cluster topology, routing, and proxying requests to the underlying data nodes.")
    Component(InMemoryDataStore, "In-Memory Data Store", "Redis In-Memory Data Store", "Provides low-latency access for caching and active session/EMR data.")
    Component(PersistenceEngine, "Persistence Engine", "Redis Persistence Engine", "Handles data persistence with AES-256 encryption for secure data storage.")
}

Rel(RedisClusterCoordinatorProxy, InMemoryDataStore, "Routes read/write operations")
Rel(RedisClusterCoordinatorProxy, PersistenceEngine, "Triggers secure disk persistence")

@enduml

Apache Kafka.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(apache_kafka, "Apache Kafka") {
    Component(Kafka_Brokers, "Kafka Brokers", "Apache Kafka (acks=all)", "Handles zero-data-loss event streaming, publishing, and consuming asynchronous clinical events.")
    Component(KRaft_Controller_Quorum, "KRaft Controller Quorum", "Apache Kafka KRaft Mode", "Manages metadata and consensus for streamlined failovers without ZooKeeper.")
    Component(Kafka_Connect, "Kafka Connect", "Kafka Connect Framework", "Provides exactly-once event syncing to PostgreSQL and AWS S3 Object Lock.")
    Component(Schema_Registry, "Schema Registry", "Confluent Schema Registry", "Stores and enforces Avro/Protobuf backward-compatibility rules for event schemas.")
    Component(Kafka_Stream_Processors, "Kafka Stream Processors", "Kafka Streams", "Performs real-time appointment clash checks and event aggregation.")
}

Rel(Kafka_Brokers, AWS_S3_Object_Lock, "Tiered storage and audit log archiving", "HTTPS")
Rel(Kafka_Brokers, Schema_Registry, "Stores schema definitions", "Kafka Protocol")

@enduml

AWS S3 Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_s3_object_lock, "AWS S3 Object Lock") {
    Component(Object_Ingestion_API, "Object Ingestion API", "AWS SDK / REST API", "Handles incoming compliance data and document uploads securely over AWS PrivateLink.")
    Component(Retention_Enforcement_Engine, "Retention Enforcement Engine", "AWS S3 Object Lock (WORM Compliance Mode)", "Enforces strict 10-year immutable retention policies on stored medical records.")
    Component(Audit_Logger, "Audit Logger", "Node.js / AWS CloudTrail integration", "Tracks and logs all data access, modifications, and retention events for compliance monitoring.")
    Component(KMS_Envelope_Encryption_Wrapper, "KMS Envelope Encryption Wrapper", "AWS KMS", "Provides cryptographic envelope encryption and enables cryptographic GDPR erasure.")
}

Rel(Object_Ingestion_API, Retention_Enforcement_Engine, "Routes uploaded data to be locked under WORM compliance mode")
Rel(Retention_Enforcement_Engine, KMS_Envelope_Encryption_Wrapper, "Encrypts and secures stored medical data objects")
Rel(Object_Ingestion_API, Audit_Logger, "Logs ingestion and access activities")

@enduml
